-- Hyprland 0.57 proof of concept: the niri setup on the scrolling layout, with Lua doing what niri
-- needed niri-dynamic-workspaces, ghostty-here --stack and window-kill for.
-- `fp` (theme, monitors, project workspaces, tool paths) is generated by ./default.nix.

local mod = "SUPER"
local ghostty = "com.mitchellh.ghostty"

-- Callable from outside, e.g. `hyprctl eval 'fp_api.project("n")'` from a DMS widget.
local api = {}
fp_api = api

local function rgb(hex)
    return "rgb(" .. hex .. ")"
end

local function sh_quote(s)
    return "'" .. (tostring(s):gsub("'", [['\'']])) .. "'"
end

local function run(cmd)
    hl.dispatch(hl.dsp.exec_cmd(cmd))
end

---------------------------------------------------------------------------------------------------
-- Outputs, environment, look
---------------------------------------------------------------------------------------------------

for _, m in ipairs(fp.monitors) do
    if m.enable then
        hl.monitor({
            output = m.name,
            mode = m.mode,
            position = m.position,
            scale = m.scale,
            transform = m.transform,
            -- 3: only while a fullscreen window has game/video content, the nearest to niri's
            -- per-window on-demand VRR (see the content rules below).
            vrr = m.vrr and 3 or 0,
        })
    else
        hl.monitor({ output = m.name, disabled = true })
    end
end

hl.env("NIXOS_OZONE_WL", "1")
hl.env("XCURSOR_THEME", "Adwaita")
hl.env("XCURSOR_SIZE", "24")

hl.config({
    general = {
        layout = "scrolling",
        gaps_in = 5,
        gaps_out = 10,
        border_size = 2,
        col = {
            active_border = rgb(fp.colors.accent),
            inactive_border = rgb(fp.colors.ui),
        },
    },
    decoration = {
        rounding = 8,
        blur = { enabled = true, xray = false },
        shadow = { enabled = true, range = 30, render_power = 2, offset = { 0, 5 }, color = "rgba(" .. fp.colors.black .. "99)" },
    },
    scrolling = {
        column_width = 0.5,
        explicit_column_widths = "0.33333, 0.5, 0.66667, 1.0",
        -- niri keeps a lone column at its own width and stops at the strip's ends.
        fullscreen_on_one_column = false,
        wrap_focus = false,
        wrap_swapcol = false,
    },
    group = {
        col = { border_active = rgb(fp.colors.accent), border_inactive = rgb(fp.colors.ui) },
        -- niri's tab indicator: a bare strip, and none for a single window.
        groupbar = {
            col = { active = rgb(fp.colors.accent), inactive = rgb(fp.colors.ui) },
            render_titles = false,
            gradients = false,
            disable_when_only = true,
        },
    },
    input = {
        kb_layout = "eu",
        accel_profile = "flat",
        -- Hover focuses; the tape only moves for binds and clicks (untested against niri's
        -- max-scroll-amount 0%).
        follow_mouse = 1,
    },
    binds = {
        window_direction_monitor_fallback = true,
    },
    misc = {
        middle_click_paste = false,
        background_color = "rgb(" .. fp.colors.bg .. ")",
        disable_hyprland_logo = true,
        force_default_wallpaper = 0,
        -- Stands in for niri's honor-xdg-activation-with-invalid-serial.
        focus_on_activate = true,
    },
    ecosystem = {
        no_update_news = true,
        no_donation_nag = true,
    },
})

-- niri: eased 150 ms open/close under a 0.8 slowdown, and its critically damped view spring.
hl.curve("fpOut", { type = "bezier", points = { { 0.25, 0.46 }, { 0.45, 0.94 } } })
hl.curve("fpSpring", { type = "spring", mass = 1, stiffness = 800, damping = 56.6 })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 1.2, bezier = "fpOut", style = "popin 90%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.2, bezier = "fpOut", style = "popin 90%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 4, spring = "fpSpring" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, spring = "fpSpring", style = "slidevert" })

-- DMS surfaces blur what is behind them rather than only the wallpaper.
hl.layer_rule({ match = { namespace = "^dms:" }, blur = true, xray = false, ignore_alpha = 0 })

---------------------------------------------------------------------------------------------------
-- Window rules
---------------------------------------------------------------------------------------------------

-- agent-note-open's glow viewer floats over the session that opened it.
hl.window_rule({
    match = { class = [[^dev\.fireproof\.notes$]] },
    float = true,
    center = true,
    size = { "monitor_w*0.5", "monitor_h*0.8" },
})

-- Content types drive the per-monitor `vrr = 3` above; desktop apps stay out of VRR.
hl.window_rule({ match = { class = "^steam_app_" }, content = "game" })
hl.window_rule({ match = { class = "^gamescope$" }, content = "game" })
hl.window_rule({ match = { class = "^mpv$" }, content = "video" })

-- Shadows only on floating windows.
hl.window_rule({ match = { float = false }, no_shadow = true })

---------------------------------------------------------------------------------------------------
-- Scrolling helpers: niri's column actions that Hyprland lacks, written against the Lua layout data
---------------------------------------------------------------------------------------------------

-- A tiled window's scrolling column ({ index, width, windows }); nil when floating.
local function column(w)
    local l = w and w.layout
    return l and l.column or nil
end

-- Lowest and highest column index on `w`'s workspace.
local function column_range(w)
    local lo, hi
    for _, o in ipairs(hl.get_workspace_windows(w.workspace --[[@as HL.Workspace]])) do
        local c = column(o)
        if c then
            lo = math.min(lo or c.index, c.index)
            hi = math.max(hi or c.index, c.index)
        end
    end
    return lo, hi
end

-- The enabled monitor nearest to `m` on the left ("l") or right ("r"), by layout position.
local function neighbour_monitor(m, dir)
    local best
    for _, o in ipairs(hl.get_monitors()) do
        if o.id ~= m.id and o.enabled and not o.is_mirror then
            local ok = (dir == "l" and o.x < m.x) or (dir == "r" and o.x > m.x)
            if ok and (not best or (dir == "l" and o.x > best.x) or (dir == "r" and o.x < best.x)) then
                best = o
            end
        end
    end
    return best
end

-- niri's move-column-{left,right}-or-to-monitor-*: swap within the strip, and at its edge carry the
-- whole column (every window in it, in order) to the neighbouring monitor.
function api.move_column(dir)
    local w = hl.get_active_window()
    local c = column(w)
    if not (w and c) then
        hl.dispatch(hl.dsp.window.move({ direction = dir }))
        return
    end
    local lo, hi = column_range(w)
    if (dir == "l" and c.index > lo) or (dir == "r" and c.index < hi) then
        hl.dispatch(hl.dsp.layout("swapcol " .. dir))
        return
    end
    local target = w.monitor and neighbour_monitor(w.monitor, dir)
    if not target then
        return
    end
    for i, cw in ipairs(c.windows) do
        hl.dispatch(hl.dsp.window.move({ window = cw, monitor = target, follow = true }))
        if i > 1 then
            -- Each window lands as a new column right of the previous one; fold it back in.
            hl.dispatch(hl.dsp.focus({ window = cw }))
            hl.dispatch(hl.dsp.layout("consume_or_expel prev"))
        end
    end
    hl.dispatch(hl.dsp.focus({ window = w }))
end

-- niri's focus-column-first/last.
function api.focus_column(which)
    local w = hl.get_active_window()
    if not (w and column(w)) then
        return
    end
    local lo, hi = column_range(w)
    local want = which == "first" and lo or hi
    for _, o in ipairs(hl.get_workspace_windows(w.workspace --[[@as HL.Workspace]])) do
        local c = column(o)
        if c and c.index == want then
            hl.dispatch(hl.dsp.focus({ window = o }))
            return
        end
    end
end

-- niri's move-column-to-first/last.
function api.move_column_to(which)
    local w = hl.get_active_window()
    local c = column(w)
    if not c then
        return
    end
    local lo, hi = column_range(w)
    local steps = which == "first" and c.index - lo or hi - c.index
    for _ = 1, steps do
        hl.dispatch(hl.dsp.layout("swapcol " .. (which == "first" and "l" or "r")))
    end
end

-- niri's set-window-height ±N%: Hyprland resizes in pixels, so scale by the monitor.
local function grow_height(frac)
    local m = hl.get_active_monitor()
    if m then
        hl.dispatch(hl.dsp.window.resize({ x = 0, y = math.floor(m.height / m.scale * frac), relative = true }))
    end
end

---------------------------------------------------------------------------------------------------
-- Project workspaces (niri-dynamic-workspaces) and terminals (ghostty-here)
---------------------------------------------------------------------------------------------------

-- Static workspaces Mod+q..t, kept alive on the primary output like niri's "01".."05".
local static = { "q", "w", "e", "r", "t" }
local static_names = { q = "browser", r = "music", t = "diff" }
for i, key in ipairs(static) do
    if fp.primary ~= "" then
        hl.workspace_rule({
            workspace = tostring(i),
            monitor = fp.primary,
            persistent = true,
            default = i == 1,
            default_name = static_names[key],
        })
    end
    hl.bind(mod .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Workspace name -> project. Metadata comes from config, so nothing is encoded in the name and
-- nothing is lost when a reload resets Lua state.
local function project_of(ws)
    if not ws then
        return nil
    end
    for _, p in pairs(fp.workspaces) do
        if p.name == ws.name then
            return p
        end
    end
end

-- Spawn tag -> continuation; window.open below advances the chain.
local waiting = {}
local spawn_seq = 0

-- Spawns `cmds` one at a time onto workspace `sel`, each after the previous window opened (or 5 s
-- passed, e.g. `code` handing off to a running instance), so columns follow command order. The
-- exec rule ties each window to its own process, so a workspace switch meanwhile changes nothing.
local function spawn_in_order(cmds, sel, i)
    i = i or 1
    local cmd = cmds[i]
    if not cmd then
        return
    end
    spawn_seq = spawn_seq + 1
    local tag = "fpspawn" .. spawn_seq
    local done = false
    local function advance()
        if done then
            return
        end
        done = true
        waiting[tag] = nil
        spawn_in_order(cmds, sel, i + 1)
    end
    waiting[tag] = advance
    hl.exec_cmd(cmd, { workspace = sel .. " silent", tag = "+" .. tag })
    hl.timer(advance, { timeout = 5000, type = "oneshot" })
end

-- Focus a project's workspace, creating it and starting its programs the first time. Hyprland
-- destroys it again once it is empty and unfocused, so no cleanup daemon is needed.
function api.project(key)
    local p = fp.workspaces[key]
    if not p then
        return
    end
    local sel = "name:" .. p.name
    local fresh = hl.get_workspace(sel) == nil
    hl.dispatch(hl.dsp.focus({ workspace = sel }))
    if fresh then
        spawn_in_order(p.programs, sel)
    end
end

function api.move_to_project(key)
    local p = fp.workspaces[key]
    if p then
        hl.dispatch(hl.dsp.window.move({ workspace = "name:" .. p.name, follow = false }))
    end
end

function api.close_project(key)
    local p = fp.workspaces[key]
    if not p or not hl.get_workspace("name:" .. p.name) then
        return
    end
    for _, w in ipairs(hl.get_workspace_windows("name:" .. p.name)) do
        hl.dispatch(hl.dsp.window.close({ window = w }))
    end
end

-- A key-per-project submap stands in for the overlay; a notification lists the keys meanwhile.
local hints = {}
local keys = {}
for key in pairs(fp.workspaces) do
    keys[#keys + 1] = key
end
table.sort(keys)

local function project_submap(name, title, action)
    local lines = { title }
    for _, key in ipairs(keys) do
        lines[#lines + 1] = key .. "  " .. fp.workspaces[key].name
    end
    hints[name] = table.concat(lines, "\n")
    hl.define_submap(name, function()
        for _, key in ipairs(keys) do
            local function pick()
                hl.dispatch(hl.dsp.submap("reset"))
                action(key)
            end
            -- Mod may still be held from the bind that opened the submap.
            hl.bind(key, pick)
            hl.bind(mod .. " + " .. key, pick)
        end
        hl.bind("escape", hl.dsp.submap("reset"))
    end)
end

project_submap("fp-switch", "Switch to project", api.project)
project_submap("fp-move", "Move window to project", api.move_to_project)
project_submap("fp-close", "Close project's windows", api.close_project)

local hint
hl.on("keybinds.submap", function(name)
    if hint then
        hint:dismiss()
        hint = nil
    end
    if hints[name] then
        hint = hl.notification.create({ text = hints[name], timeout = 10000 })
    end
end)

-- ghostty-here: start where you are working. Directory order: the focused terminal's shell, the
-- project's directory, another terminal's shell on this workspace, then $HOME. With `stack`, the
-- new window joins the focused column instead of opening one beside it.
local function terminal(stack)
    local w = hl.get_active_window()
    local ws = hl.get_active_workspace()
    local p = project_of(ws)
    local pids = {}
    if w and w.class == ghostty then
        pids[#pids + 1] = tostring(w.pid)
    end
    if not (p and p.path) and ws then
        for _, o in ipairs(hl.get_workspace_windows(ws)) do
            if o.class == ghostty and o ~= w then
                pids[#pids + 1] = tostring(o.pid)
            end
        end
    end
    -- The /proc walk runs in the spawned shell, not on the compositor thread.
    local cmd = string.format(
        'exec ghostty --working-directory="$(%s %s %s)"',
        fp.bin.shell_cwd,
        sh_quote((p and p.path) or fp.home),
        table.concat(pids, " ")
    )
    if stack and w and not w.floating then
        hl.exec_cmd(cmd, { tag = "+fpstack" })
    else
        hl.exec_cmd(cmd)
    end
end

hl.on("window.open", function(w)
    for _, t in ipairs(w.tags) do
        local tag = t:gsub("%*$", "")
        if tag == "fpstack" then
            -- It opened as the column right of the one it was launched from; fold it in at the
            -- bottom. Plain `consume` would merge it into the next column instead (0.57, tested).
            hl.dispatch(hl.dsp.focus({ window = w }))
            hl.dispatch(hl.dsp.layout("consume_or_expel prev"))
        elseif waiting[tag] then
            waiting[tag]()
        end
    end
end)

